using System;using System.IO;using System.Net;using System.Collections;using System.Collections.Generic;using System.Linq;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;
// Only the packaged, pinned model catalog can select download URLs/paths.
class ModelDownloads {
  static string Models=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","models"));
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=16*1024*1024};}
  static Dictionary<string,object> Current;static CancellationTokenSource Cancellation;static object Gate=new object();
  static List<Dictionary<string,object>> Entries(){string file=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"model-catalog.json");if(!File.Exists(file))return new List<Dictionary<string,object>>();var data=Json().Deserialize<Dictionary<string,object>>(File.ReadAllText(file));var entries=((IEnumerable)data["models"]).Cast<Dictionary<string,object>>().ToList();if(data.ContainsKey("whisperModels"))entries.AddRange(((IEnumerable)data["whisperModels"]).Cast<Dictionary<string,object>>());if(data.ContainsKey("starterModels"))entries.AddRange(((IEnumerable)data["starterModels"]).Cast<Dictionary<string,object>>());return entries;}
  static IEnumerable<Dictionary<string,object>> Files(Dictionary<string,object> entry){return ((IEnumerable)entry["files"]).Cast<Dictionary<string,object>>();}
  static string Folder(Dictionary<string,object> entry){return Path.Combine(Models,entry.ContainsKey("kind")&&entry["kind"].ToString()=="whisper"?"whisper":"llm",entry["id"].ToString());}
  static string SafeFile(Dictionary<string,object> entry,string name){string folder=Path.GetFullPath(Folder(entry));string target=Path.GetFullPath(Path.Combine(folder,name));if(!target.StartsWith(folder+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Invalid catalog model path");for(var d=new DirectoryInfo(Path.GetDirectoryName(target));d!=null&&d.FullName.StartsWith(Models,StringComparison.OrdinalIgnoreCase);d=d.Parent)if(d.Exists&&(d.Attributes&FileAttributes.ReparsePoint)!=0)throw new Exception("Model path cannot be a junction");if(File.Exists(target)&&(File.GetAttributes(target)&FileAttributes.ReparsePoint)!=0)throw new Exception("Model file cannot be a symbolic link");return target;}
  static bool Ready(Dictionary<string,object> e){try{string marker=SafeFile(e,".model-ready.json");if(!File.Exists(marker))return false;var receipt=Json().Deserialize<Dictionary<string,object>>(File.ReadAllText(marker));return receipt["revision"].ToString()==e["revision"].ToString()&&Files(e).All(f=>{string p=SafeFile(e,f["path"].ToString());return File.Exists(p)&&new FileInfo(p).Length==Convert.ToInt64(f["bytes"]);});}catch{return false;}}
  public static bool InstallationReady(string id,bool legacyReady){var e=Entries().SingleOrDefault(x=>x["id"].ToString()==id);if(e==null)return legacyReady;return File.Exists(SafeFile(e,".model-install.json"))?Ready(e):legacyReady;}
  public static bool Contains(string id){return Entries().Any(e=>e["id"].ToString()==id&&!e.ContainsKey("legacyLiteRt"));}
  public static IEnumerable<object> ModelsList(){foreach(var e in Entries().Where(e=>!e.ContainsKey("kind")||e["kind"].ToString()!="whisper").Where(e=>!e.ContainsKey("legacyLiteRt")))yield return new{id=e["id"],backend=e["backend"],file=e.ContainsKey("file")?e["file"]:null,ready=Ready(e),bytes=e["bytes"]};}
  public static object Status(){lock(Gate)return Current==null?new{state="idle"}:(object)new Dictionary<string,object>(Current);}
  static void Update(params object[] values){lock(Gate){for(int i=0;i<values.Length;i+=2)Current[(string)values[i]]=values[i+1];}}
  public static object Start(string id){lock(Gate){if(Current!=null&&(Current["state"].ToString()=="downloading"||Current["state"].ToString()=="cancelling"))throw new Exception("Another model download is in progress");var entry=Entries().SingleOrDefault(e=>e["id"].ToString()==id);if(entry==null)throw new Exception("Model is not in the packaged download catalog");long remaining=Files(entry).Sum(f=>{string p=SafeFile(entry,f["path"].ToString());string part=p+".download";return File.Exists(p)?0L:Math.Max(0,Convert.ToInt64(f["bytes"])-(File.Exists(part)?new FileInfo(part).Length:0L));});ModelFiles.EnsureSpace(remaining);string lockPath=SafeFile(entry,".download.lock");Directory.CreateDirectory(Path.GetDirectoryName(lockPath));FileStream fileLock;try{fileLock=new FileStream(lockPath,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None,8,FileOptions.DeleteOnClose);}catch(IOException){throw new Exception("This model is being downloaded in another Chrome profile");}try{File.WriteAllText(SafeFile(entry,".model-install.json"),Json().Serialize(new{id=id,revision=entry["revision"]}),new UTF8Encoding(false));}catch{fileLock.Dispose();throw;}Cancellation=new CancellationTokenSource();var token=Cancellation.Token;Current=new Dictionary<string,object>{{"modelId",id},{"state","downloading"},{"bytes",0L},{"total",entry["bytes"]},{"file",""},{"error",null}};Task.Run(()=>{using(fileLock)Run(entry,token);});return new Dictionary<string,object>(Current);}}
  public static object Cancel(){lock(Gate){if(Current!=null&&Current["state"].ToString()=="downloading"){Current["state"]="cancelling";Cancellation.Cancel();}return Status();}}
  static string Hash(string path){using(var h=SHA256.Create())using(var f=File.OpenRead(path))return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
  static void Run(Dictionary<string,object> entry,CancellationToken token){long done=0;var receipts=new List<object>();try{
    ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;
    foreach(var spec in Files(entry)){token.ThrowIfCancellationRequested();string name=spec["path"].ToString(),target=SafeFile(entry,name),part=SafeFile(entry,name+".download");long size=Convert.ToInt64(spec["bytes"]);string expected=spec["sha256"] as string;Update("file",name,"bytes",done);Directory.CreateDirectory(Path.GetDirectoryName(target));
      if(File.Exists(target)){if(new FileInfo(target).Length!=size||(expected!=null&&Hash(target)!=expected))throw new Exception("Existing model file differs; preserved: "+name);done+=size;receipts.Add(new{file=name,sha256=expected??Hash(target),bytes=size});continue;}
      long offset=File.Exists(part)?new FileInfo(part).Length:0;if(offset>size)throw new Exception("Partial file exceeds expected size: "+name);
      if(offset<size){var uri=new Uri(spec["url"].ToString());if(uri.Scheme!="https"||uri.Host!="huggingface.co"||!uri.AbsolutePath.Contains("/resolve/"+entry["revision"]+"/"))throw new Exception("Invalid pinned model URL");var request=(HttpWebRequest)WebRequest.Create(uri);request.Timeout=60000;request.ReadWriteTimeout=60000;request.UserAgent="LiveLocalTranslator/0.4.3 local model downloader";if(offset>0)request.AddRange(offset);
        using(token.Register(()=>request.Abort()))using(var response=(HttpWebResponse)request.GetResponse()){
          if(offset>0&&response.StatusCode!=HttpStatusCode.PartialContent)offset=0;
          using(var input=response.GetResponseStream())using(var output=new FileStream(part,offset>0?FileMode.Append:FileMode.Create,FileAccess.Write,FileShare.None)){byte[] buffer=new byte[256*1024];int n;long position=offset,checkedAt=offset;DateTime last=DateTime.MinValue;while((n=input.Read(buffer,0,buffer.Length))>0){token.ThrowIfCancellationRequested();if(position+n>size)throw new Exception("Model response exceeds expected size");if(position-checkedAt>=64L*1024*1024){ModelFiles.EnsureSpace(0);checkedAt=position;}output.Write(buffer,0,n);position+=n;if((DateTime.UtcNow-last).TotalMilliseconds>200){Update("bytes",done+position);last=DateTime.UtcNow;}}output.Flush(true);}
        }
      }
      token.ThrowIfCancellationRequested();if(new FileInfo(part).Length!=size)throw new Exception("Incomplete model download: "+name);string hash=Hash(part);if(expected!=null&&hash!=expected)throw new Exception("Model SHA256 mismatch: "+name);File.Move(part,target);receipts.Add(new{file=name,sha256=hash,bytes=size});done+=size;Update("bytes",done);
    }
    File.WriteAllText(SafeFile(entry,".model-ready.json"),Json().Serialize(new{id=entry["id"],revision=entry["revision"],at=DateTime.UtcNow.ToString("o"),files=receipts}),new UTF8Encoding(false));Update("state","complete","bytes",done,"file","");
  }catch(Exception e){Update("state",token.IsCancellationRequested?"cancelled":"error","error",token.IsCancellationRequested?null:e.Message);}}
}
